-- Name: Price Variant AB - Closed loop funnel - Gemini - Syed
-- Source: Syed Athena Saved Queries export
-- Prefer dataplatform MCP / Iceberg for runs; adjust only date params.
-- Default country: IND when applicable.

WITH ui_session_flags AS ( -- Aggregate UI events to session level to prevent row duplication SELECT mri_session_id, MAX(CASE WHEN event_name = 'SL loaded' THEN 1 ELSE 0 END) as sl_Land, MAX(CASE WHEN event_value = 'Yes' THEN 1 ELSE 0 END) as Price_range FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-25 18:30:00' -- AND header_bu = 'BUS' AND selected_country = 'India' -- AND event_src = 'Android' -- AND event_name IN ('SL loaded') AND event_group = 'ab_exp_srp_price' GROUP BY 1 ), base_events AS ( -- Combine all relevant events into a single chronological stream per session SELECT mri_session_id, route_id, __time, 'SRP' as stage, NULL as event_val FROM "user_interaction"."search_route_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-25 18:30:00' AND country = 'IND' UNION ALL SELECT mri_session_id, route_id, __time, 'SL' as stage, NULL as event_val FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-25 18:30:00' AND country = 'IND' UNION ALL SELECT mri_session_id, route_id, __time, 'PAX' as stage, NULL as event_val FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-25 18:30:00' AND country = 'IND' UNION ALL SELECT mri_session_id, route_id, __time, 'PAY' as stage, NULL as event_val FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-25 18:30:00' AND country = 'IND' UNION ALL SELECT mri_session_id, route_id, __time, 'CONF' as stage, tin as event_val FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-05-25 18:30:00' AND country = 'IND' AND status = 200 ), sl_instances AS ( -- Identify every SL load and find the time of the NEXT SL load to bound the instance SELECT b.*, LEAD(__time) OVER (PARTITION BY mri_session_id ORDER BY __time) as next_sl_time FROM base_events b WHERE stage = 'SL' ), sequenced_funnel AS ( -- For every SL instance, check what events occurred before the next SL load SELECT sl.mri_session_id, sl.route_id, sl.__time as sl_time, srp.os, srp.channel, srp.user_type, srp.exp_Variant, CASE WHEN u.sl_Land = 1 AND u.Price_range = 1 THEN 'Price Range Tuple' ELSE 'Normal Tuple' END AS tuple_type, -- Check for progression stages within this specific SL window MAX(CASE WHEN b.stage = 'PAX' AND b.__time > sl.__time AND (b.__time < sl.next_sl_time OR sl.next_sl_time IS NULL) THEN 1 ELSE 0 END) as reached_pax, MAX(CASE WHEN b.stage = 'PAY' AND b.__time > sl.__time AND (b.__time < sl.next_sl_time OR sl.next_sl_time IS NULL) THEN 1 ELSE 0 END) as reached_pay, MAX(CASE WHEN b.stage = 'CONF' AND b.__time > sl.__time AND (b.__time < sl.next_sl_time OR sl.next_sl_time IS NULL) THEN 1 ELSE 0 END) as reached_conf, -- Check for "Back to SRP" within this specific SL window MAX(CASE WHEN b.stage = 'SRP' AND b.__time > sl.__time AND (b.__time < sl.next_sl_time OR sl.next_sl_time IS NULL) THEN 1 ELSE 0 END) as back_to_srp FROM sl_instances sl JOIN ( -- Get SRP context for the session/route SELECT mri_session_id, route_id, os, channel, user_type, CASE WHEN contains(channel_exp_info, 'priceVariantAB:V0') THEN 'V0' WHEN contains(channel_exp_info, 'priceVariantAB:V1') THEN 'V1' WHEN contains(channel_exp_info, 'priceVariantAB:V2') THEN 'V2' WHEN contains(channel_exp_info, 'priceVariantAB:V3') THEN 'V3' WHEN contains(channel_exp_info, 'priceVariantAB:V4') THEN 'V4' ELSE 'others' END AS exp_Variant FROM "user_interaction"."search_route_details" WHERE __time >= TIMESTAMP '2026-05-21 18:30:00' AND __time < TIMESTAMP '2026-04-15 18:30:00' ) srp ON sl.mri_session_id = srp.mri_session_id AND sl.route_id = srp.route_id LEFT JOIN ui_session_flags u ON sl.mri_session_id = u.mri_session_id -- using your existing CTE logic LEFT JOIN base_events b ON sl.mri_session_id = b.mri_session_id GROUP BY 1,2,3,4,5,6,7,8 ) SELECT COALESCE(os, channel) AS saleschannel, exp_Variant, user_type, tuple_type, CASE WHEN reached_pax = 1 THEN 'proceeded' WHEN back_to_srp = 1 AND reached_pax = 0 THEN 'back to SRP' ELSE 'dropped off' END AS user_behaviour, COUNT(*) AS sl_instances, -- Total times SL was loaded SUM(reached_pax) AS pax_instances, SUM(reached_pay) AS pay_instances, SUM(reached_conf) AS conf_instances FROM sequenced_funnel GROUP BY 1, 2, 3, 4, 5 ORDER BY 1, 2, 5;
